ProjectALife.DialogueShards["scenes_misc_3"] = {
{"s13_eng_reserved_target_001","demo",3,"reg=military|role=soldier_nco,soldier",{1,"The Carver approach is a reserved target, means we don't fire it on our own hook",2,"Who fires it then?",1,"Somebody with the authority, in writing, by name, there's a demolition guard, a firing party, and a man who says go",3,"And who is he?",1,"Best I can tell he's a colonel who ain't answered a radio in nine days"}},
{"s13_eng_authority_002","demo",2,"reg=military|mood=angry",{1,"So we sit on a charged bridge waiting on a colonel",2,"That's the doctrine",1,"Doctrine was wrote for a war that had a rear area in it"}},
{"s13_eng_prep_not_fire_003","demo",2,"reg=military|tmp=veteran",{1,"We prepare it, we don't fire it, two jobs, two words, and people mix 'em up",2,"And if they come across before he calls?",1,"Then it's the longest thirty seconds of my life and then it's whatever I decide",1,"Don't make me say any more than that out loud"}},
{"s13_eng_boreholes_004","demo",2,"reg=military|world=road",{1,"Six holes, five foot deep, five foot apart, across both lanes",2,"With what, a shovel?",1,"Pavement breaker off the five-ton, then the auger, two hours if the compressor holds"}},
{"s13_eng_cratering_charge_005","demo",2,"reg=military|world=road",{1,"Forty pounds a hole, tamped, det cord ring main across the top of 'em",2,"Ring main?",1,"So if one leg goes bad the ring still carries - you don't get a second try on a road"}},
{"s13_eng_galvanometer_006","demo",3,"reg=military|role=soldier_nco",{1,"Check the circuit",2,"Checked it",1,"Check it again with the galvanometer and let me watch the needle myself",3,"He's checked it twice, Sergeant",1,"Then he'll check it three times and we'll all be bored and alive"}},
{"s13_eng_two_man_007","demo",2,"reg=military|tmp=veteran",{1,"Nobody touches the caps alone, two men, every time, no exceptions",2,"Even you?",1,"Especially me, I've done it long enough to get careless and not notice"}},
{"s13_eng_crimp_teeth_008","demo",2,"reg=military|mood=funny",{1,"Don't you crimp a cap with your teeth",2,"I wasn't",1,"Sowders did in 1984, he talks fine, he just ain't got the front two"}},
{"s13_eng_time_fuse_009","demo",2,"reg=military",{1,"Time fuse burns about forty seconds a foot - burn a test length off every roll",2,"Why every roll?",1,"'Cause the roll don't care what the book says - burn it and count it yourself"}},
{"s13_eng_fire_in_hole_010","demo",3,"reg=military",{1,"Call it",2,"Fire in the hole! Fire in the hole! Fire in the hole!",3,"Ain't nobody out there to hear it",1,"We say it three times 'cause one day somebody is - I ain't changing it for a quiet Tuesday"}},
{"s13_eng_it_didnt_drop_011","demo",2,"reg=military|mood=angry",{1,"It didn't drop",2,"What do you mean it didn't drop?",1,"Approach is gone and the deck's sitting there like nothing happened - two foot of dirt off the ramp"}},
{"s13_eng_who_walks_down_012","demo",3,"reg=military|role=soldier_nco",{1,"Somebody's got to walk down and see which leg didn't take",2,"Thirty minutes first",1,"Thirty minutes first, then I go",3,"Sergeant, let me",1,"No, it's my circuit, it's got my name on it, that's all"}},
{"s13_eng_misfire_rule_013","demo",2,"reg=military|tmp=veteran",{1,"You never pull on the wire - Disconnect at the machine, short the leads, and wait",2,"Wait how long?",1,"Long enough to smoke one and hate yourself, thirty minutes, minimum, and I mean minimum"}},
{"s13_eng_c4_blocks_014","demo",2,"reg=military|world=vehicle",{1,"How much C-4 have we got left?",2,"Eleven blocks and a half, half's been in the truck since drill in April",1,"It's fine - don't go bad, just gets stiff - warm it in your hands and keep it off the heater"}},
{"s13_eng_abutment_015","demo",2,"reg=military|tmp=veteran|world=vehicle",{1,"You don't cut the span, you take the approach, cheaper, faster, same answer for a truck",2,"And for people on foot?",1,"People on foot get across anything, we ain't stopping men on foot and we never were"}},
{"s13_eng_count_the_far_side_016","demo",3,"reg=military|hour=4,9|mood=grim|world=vehicle,cars",{1,"Before we shoot it, somebody count who's still on the far side",2,"That ain't our job",1,"It's somebody's job and there is nobody else out here",3,"I counted, fourteen vehicles and a church van up at the turnaround",1,"Then it don't go at first light, it goes when that van's on this side"}},
{"s13_eng_van_comes_017","demo",2,"reg=military|mood=warm|world=vehicle",{1,"Van crossed at ten past six - everybody's over",2,"You sure? Count 'em",1,"Counted twice, forty-one people, two dogs and a cooler"}},
{"s13_eng_after_the_bang_018","demo",2,"reg=military|mood=grim|world=window,road",{1,"You could hear it in Rosewood, windows in the church rattled",2,"And the road?",1,"There's a hole forty foot long in it, loudest thing I've ever done and all it is is a hole"}},
{"s13_eng_culvert_022","demo",2,"reg=military|mood=funny|world=road",{1,"Two blocks in the culvert mouth and the road caves in on its own",2,"That's cheap",1,"Water does the rest by Thursday, best engineering there is, the kind you don't pay for"}},
{"s13_eng_last_charges_027","demo",2,"reg=military|world=vehicle,road",{1,"What's left in the truck?",2,"Nine blocks, a spool of det cord, forty caps, and one blasting machine",1,"Then we've got one more road in us - pick it careful and pick it sober"}},
{"s13_eng_bridge_didnt_need_057","demo",2,"reg=military|mood=grim",{1,"Did we need to do the Carver?",2,"Ask me in a year",1,"I'm asking now",2,"In a year there'll be folks on one side who can't get to folks on the other, and that's us",2,"They'd also have come across it Tuesday night in a line - both things are true"}},
{"s13_eng_the_machine_062","demo",1,"reg=military|role=soldier_nco|world=road",{1,"The blasting machine's a green box with a handle and a needle on it - that's all it is",1,"You twist the handle, the needle jumps, and a road quits being a road",1,"Footlocker, padlock, and I've got the only key - call it sense"}},
{"s13_wire_deserter_talk_035","desert",2,"reg=military|role=soldier_nco,deserter",{1,"Whitt's gone, rifle's on his cot with the magazine out and a note under it",2,"Note say anything?",1,"Says his mother's in Vine Grove and he's sorry, two lines, printed neat",2,"He left the rifle, that's a man trying to stay a good man on his way out"}},
{"s13_wire_who_chases_036","desert",2,"reg=military|world=vehicle",{1,"You want me to go after him?",2,"With what authority and in whose truck?",1,"That's a no",2,"That's a no, mark him absent and let the paper do it"}},
{"s13_law_property_room_008","evidence",2,"reg=law|mood=angry",{1,"Somebody cut the hasp off the property room",2,"What's gone?",1,"Two shotguns, a box of .357, and four hundred dollars of weed out of the Sizemore case",2,"Well, somebody's having a better week than us"}},
{"s13_law_evidence_tape_056","evidence",2,"reg=law|world=building",{1,"I taped off the Sizemore porch and wrote the date on the tape",2,"Who's coming to work it?",1,"Nobody, but there's a date on it now, and a date is more than nothing"}},
{"exp_family_nickname","family_history",2,"reg=family|st=friendly,neutral,careful",{1,"Hey, don't call me that",2,"Sorry, grandma always-- I didn't think",1,"No, it's... actually, no - you can, just caught me funny",2,"Okay, you tell me if you want me to stop"}},
{"exp_family_seatbelt","family_history",2,"reg=family|st=friendly,neutral,careful",{1,"Dad'd pull on your seat belt, even after he heard it click",2,"And you'd go DAAAD, like he was killing you",1,"I know - God, I know",2,"He never minded, he'd just pull on mine next"}},
{"exp_family_goodplates","family_history",2,"reg=family|st=friendly,neutral,careful",{1,"All those plates in the cabinet, the nice ones - never used 'em",2,"Not even Christmas?",1,"Paper plates - Mom didn't want anyone breaking the good ones",2,"Mine too, kept the price stickers on the bottoms and everything"}},
{"ordinary_family_table","family_memory",2,"reg=family|st=friendly,neutral|world=building",{1,"Keep remembering the kitchen table",2,"What about it?",1,"Wobbled, spent years meaning to fix the short leg",2,"Funny what turns into a thing you'd like to do again"}},
{"ordinary_family_recipe","family_memory",2,"reg=family|st=neutral,friendly",{1,"Never wrote down how she made the biscuits",2,"You watched her do it, though",1,"She'd say a little of this, a little of that, like that was a measurement",2,"Maybe one day we'll get a few batches wrong and figure it out"}},
{"exp_rescue_not_heard","fatigue",2,"reg=rescue|st=friendly,neutral,careful",{1,"Mm-hm - yeah",1,"Sorry-- what? I didn't hear any of that",2,"I asked when you last slept",1,"Oh, well, that probably answers it",2,"It really does"}},
{"ordinary_short_orders","fatigue",2,"reg=military|tmp=seasoned,veteran|st=neutral,careful",{1,"You're getting quiet",2,"I'm saving the useful words",1,"Got many left?",2,"A few - don't spend them for me"}},
{"ordinary_elite_check","fatigue",2,"reg=elite|st=neutral,careful",{1,"How's your concentration?",2,"Getting expensive",1,"Say when it slips",2,"Just did"}},
{"ordinary_crew_silence","fatigue",2,"reg=gang,crime|st=neutral,careful",{1,"You've been staring a while",2,"Thinking",1,"That's new",2,"Don't interrupt, might not happen again"}},
{"ordinary_swat_hands","fatigue",2,"reg=swat|st=neutral,careful",{1,"Hands steady?",2,"Steadier than my stomach",1,"Don't hide it if that changes",2,"Wasn't planning to make it your surprise"}},
{"ordinary_first_watch","fear",2,"reg=civilian,family|tmp=fresh|st=neutral,friendly",{1,"Do you ever stop jumping at things?",2,"I stopped apologizing for it",1,"That's not what I asked",2,"It's the best answer I've got"}},
{"ordinary_not_brave","fear",2,"reg=civilian,family|tmp=fresh|st=neutral,friendly",{1,"You look like you're handling this better",2,"I'm just quiet when I'm frightened",1,"Wish I was",2,"Don't, sometimes I need to hear somebody else say it"}},
{"fw_oct09_fish_01","fishing",2,"world=water",{1,"Anything biting?",2,"Not yet, quit splashing around"}},
{"fw_oct09_fish_02","fishing",2,"world=water",{1,"Wouldn't mind a fish right now",2,"I'd eat the damn bait if we had any left"}},
{"fw_oct09_fish_03","fishing",2,"world=water",{1,"Keep watching my back, will you?",2,"I am, you watch the line"}},
{"fw_oct09_fish_04","fishing",2,"world=water",{1,"I think I felt something",2,"Don't yank it yet, give it a second"}},
{"fw_oct09_fish_05","fishing",2,"world=water",{1,"Used to come out here with my dad",2,"Mine never could sit still long enough"}},
{"fw_oct09_fish_06","fishing",2,"world=water",{1,"If I catch a boot, I'm throwing it at you",2,"Check the size first, mine are falling apart"}},
{"fw_oct09_fish_07","fishing",2,"world=water",{1,"Fish don't know a damn thing happened",2,"Lucky bastards"}},
{"fw_oct09_fish_08","fishing",2,"world=water",{1,"Don't care how small it is, I'm keeping it",2,"Split it with me, I've had nothing since we left"}},
{"s13_law_cruiser_gas_013","gear",2,"reg=law",{1,"County garage is padlocked and Rakes has got the only key",2,"Rakes is in Irvington with his mother",1,"Then I've got a quarter tank and a county thirty miles across - do that math for me"}},
{"s13_law_pistol_switch_021","gear",2,"reg=law|role=law_deputy,law_sergeant",{1,"Sheriff finally signed off on autos and they came in Wednesday",2,"Wednesday",1,"Nine millimeter, three mags apiece, I qualified on a revolver in 1979 and never fired one of these",2,"Then carry the revolver and leave the auto in the bag - ain't nobody grading you"}},
{"s13_law_impound_lot_027","gear",2,"reg=law|world=vehicle,cars,fence",{1,"Forty-one cars in the impound lot and every one's got keys in the box",2,"You thinking about it?",1,"I'm thinking whoever cuts that fence first won't be us, and that's a shame - we need a truck"}},
{"s13_law_radio_room_water_028","gear",1,"reg=law|mood=grim|world=generator",{1,"Water quit in the radio room Sunday, been hauling it up in a five gallon bucket",1,"Battery bank's holding, generator's got two days of diesel in it, maybe",1,"When it quits the county goes quiet, and nobody will know the exact minute it happened"}},
{"s13_law_take_home_car_041","gear",2,"reg=law|world=cars",{1,"They want the take-home cars back at the lot",2,"Why?",1,"Gas in one place, one set of gates to watch - it's the right call and I still hate it",2,"You hate walking home is what you hate"}},
{"s13_law_lights_only_055","gear",2,"reg=law|tmp=seasoned",{1,"Run the lights, no siren, siren brings 'em from four blocks out",2,"Code 3 without the siren ain't Code 3",1,"Then we invented something new this month - keep your window up"}},
{"s13_law_shotgun_slug_059","gear",2,"reg=law|tmp=veteran",{1,"Six shot won't do it, you want slug or you want nothing",2,"We got a case and a half of slug for this whole office",1,"Then that's what we got - count out five apiece and write down who took what"}},
{"s13_ksp_radar_off_011","gear",2,"reg=law|role=law_trooper",{1,"I turned the radar off Tuesday",2,"Why?",1,"'Cause a man doing ninety on 31W right now has got a better reason than I do"}},
{"s13_ksp_shotgun_rack_012","gear",2,"reg=law|world=vehicle",{1,"Cruiser rack holds the 870 and nothing else, no place for a rifle in a Ford",2,"Put it in the trunk",1,"It's in the trunk, wrapped in a blanket with a hundred rounds and a screwdriver"}},
{"s13_ksp_gas_card_022","gear",2,"reg=law",{1,"State gas card's no good if the pump's got no power",2,"There's a hand pump at the co-op",1,"Then that's the state motor pool now, the co-op out at Wickham's - write it down"}},
{"s13_ksp_cruiser_1100_023","gear",1,"reg=law|role=law_trooper|world=vehicle",{1,"Eleven hundred miles on this car since the fourth, eleven hundred, inside one county",1,"Oil's black, front tires are shot, air quit on Tuesday",1,"It starts, every time I turn the key it starts, I say thank you out loud now, which is new"}},
{"s13_ksp_troop_car_horn_032","gear",2,"reg=law|tmp=seasoned|world=vehicle",{1,"You can push 'em back with the car if you go slow - bumper at knee height, second gear",2,"That work?",1,"Works till one goes under and then you're walking - ask me how I come to know it"}},
{"s13_ksp_two_pumps_046","gear",2,"reg=law",{1,"You've got fuel for how long?",2,"Two more days running the county, four if I sit still",1,"Then sit still, you're worth more parked with the radio up than driving a circle"}},
{"s13_ksp_turn_in_car_049","gear",2,"reg=law|role=law_trooper|world=vehicle,door",{1,"State's property, this car, says so right there on the door",2,"You going to drive it till it dies?",1,"Drive it till it dies, lock it, and hang the key inside the post where it belongs"}},
{"s13_wire_ammo_count_025","gear",2,"reg=military",{1,"Two hundred and ten rounds a man and no resupply since the sixth",2,"That's a lot of rounds",1,"It's four minutes if anybody panics, that's why I keep saying it: nobody panics"}},
{"s13_wire_m16a1_026","gear",2,"reg=military|mood=funny",{1,"We drew A1s out of the armory, skinny barrel, full auto, front sight you set with a bullet tip",2,"Regular Army's carrying A2s",1,"Regular Army's got a lot of things, we got what was on the rack and one bore brush"}},
{"s13_wire_steel_pot_027","gear",2,"reg=military|mood=funny",{1,"You're wearing the old steel pot?",2,"Kevlar's in the truck, steel pot's got a liner I can sit on and a shell I can wash socks in",1,"You cannot wash socks in a helmet",2,"My uncle did in Korea, I'm keeping the story and the helmet both"}},
{"s13_wire_prc77_028","gear",2,"reg=military",{1,"Handset's got tape on the cord and the squelch is shot",2,"Does it transmit?",1,"It transmits, it just don't quit hissing, after a while you hear people in the hiss"}},
{"s13_wire_field_phone_029","gear",2,"reg=military",{1,"Ran wire out to post two so we quit burning batteries on the radio",2,"How far?",1,"Six hundred meters of commo wire through a bean field - crank it twice and Whitt picks up"}},
{"s13_wire_gas_mask_051","gear",2,"reg=military|mood=angry|world=building",{1,"They had us in the mask and the suit two hours Tuesday - ninety-four degrees",2,"What for?",1,"Somebody upstairs thought it was chemical - it ain't, you don't catch it out of the air",2,"Who told you that?",1,"The medic, then he told me not to say who told me"}},
{"s13_eng_dozer_ditch_020","gear",2,"reg=military|world=vehicle",{1,"I keep thinking about digging a ditch. Something to slow a crowd down",2,"With what equipment?",1,"Yeah. That's the part where my brilliant plan falls apart"}},
{"s13_eng_abatis_021","gear",2,"reg=military|world=trees,road",{1,"Drop the trees across the logging road at an angle - tops pointing back at whoever's coming",2,"Cut 'em clean through?",1,"Leave 'em hinged on the stump, hinged is an hour with a saw - cut through, you drag it with a chain"}},
{"s13_mp_wand_night_034","gear",2,"reg=military|hour=20,5|world=road",{1,"You got the wand for the light?",2,"Batteries are gone, I'm using a road flare in a coffee can",1,"That'll do - slow the arm down, fast arm makes a driver stomp it"}},
{"s13_mp_whistle_040","gear",2,"reg=military",{1,"One blast is stop, two is come ahead",2,"Nobody knows that",1,"They'll know by Thursday, people learn a whistle faster than they learn a hand"}},
{"s13_eng_saw_blade_058","gear",2,"reg=military|mood=funny|world=trees",{1,"Chain's dull and I'm out of files",2,"Sharpen it on the bench grinder down at the shop",1,"Shop's got no power, I borrowed a round file off a farmer who wanted to know what we're cutting",2,"What'd you tell him?",1,"Trees"}},
{"s13_sf_18d_kit_008","gear",2,"reg=elite|role=elite_operator",{1,"What's the medic carrying?",2,"Two bags, one's trauma, one's a clinic, sutures, lidocaine, penicillin, worm pills, a dental kit",1,"Worm pills",2,"Live with folks a week and you find out what actually kills people - it ain't gunfire"}},
{"s13_sf_car15_015","gear",2,"reg=elite|tmp=veteran",{1,"That's an old carbine",2,"It's a CAR-15, short barrel, collapsing stock, and I've had it longer than my truck",1,"Sights are beat to death",2,"Sights are fine - come look through it before you say another word about it"}},
{"s13_sf_hipower_016","gear",2,"reg=elite",{1,"You carry the Browning",2,"Thirteen rounds and it fits my hand, that's the argument, start to finish"}},
{"s13_sf_m24_017","gear",2,"reg=elite|tmp=veteran",{1,"How far are you good with it?",2,"On a range with a wind flag, eight hundred, out here, four hundred, and I'd rather three",1,"That's honest",2,"Honest is the only reason anybody lets me carry it"}},
{"s13_sf_pace_beads_018","gear",2,"reg=elite",{1,"You still counting paces on the beads?",2,"Map, compass, pace count, sun, same four things since I was twenty years old",1,"You ever get lost?",2,"Twice, both times I was carrying something fancier than a compass"}},
{"s13_delta_kit_check_025","gear",2,"reg=elite|role=elite_delta|tmp=veteran",{1,"Kit check, out loud, one at a time",2,"Six mags, water, two quarts - tape, one tourniquet on the left shoulder where it always is",1,"Batteries",2,"Four double A in the left pocket, four in the ruck - and I checked 'em on my tongue"}},
{"s13_sf_ammo_math_033","gear",2,"reg=elite|tmp=veteran",{1,"We're down to four hundred rounds for six men",2,"That's nothing",1,"It's plenty, we've fired eleven rounds in nine days and every one of 'em was aimed"}},
{"exp_raider_goodcoat","greed",2,"reg=raider|st=neutral,careful,hostile",{1,"You asked what size his coat was, before you even asked his name",2,"Was a good coat",1,"He was still wearing it, man",2,"I know that, I only asked"}},
{"ordinary_raider_shoes","greed",2,"reg=raider,outlaw|tmp=predator|st=careful,hostile",{1,"All that trouble for a pair of shoes",2,"They were good shoes",1,"They didn't fit you",2,"Didn't say they were my size"}},
{"s13_law_body_cooler_019","grim",2,"reg=law|mood=grim|world=building",{1,"Coroner's cases are stacking and there's no place cold in this town",2,"Jail kitchen's got a walk-in",1,"I know it's got a walk-in, I'm telling you I don't want to be the man who says do it",2,"Then I'll say it - put 'em in the walk-in"}},
{"s13_law_whose_house_024","grim",3,"reg=law|mood=grim",{1,"Once saw Cundiff's address on a call sheet",2,"Cundiff off Halbert Street? Your Cundiff?",1,"His wife called it in, then she quit talking and the line stayed open",3,"You offered to take the call?",1,"My partner wouldn't let me. Said he would. I still remember being relieved and ashamed at once"}},
{"s13_law_hat_on_seat_033","grim",2,"reg=law|mood=grim|world=vehicle,door",{1,"Found Combs' cruiser at the Sav Rite, doors shut, engine off, hat on the passenger seat",2,"And Combs?",1,"Hat was on the seat, that's what I've got for you"}},
{"s13_law_call_his_wife_034","grim",2,"reg=law|mood=sad",{1,"Somebody's got to tell Darlene about Combs and the phones are dead",2,"So we drive out there",1,"We drive out there, and we wear the hat and we knock like it's still a job - she's owed that"}},
{"s13_law_locker_051","grim",2,"reg=law|mood=sad|world=door",{1,"Combs' locker's still got his gym bag in it and a can of that orange pop he liked",2,"Leave it",1,"I'm not moving it, opened the door for tape and shut it real quiet, like he was asleep in there"}},
{"s13_law_wife_asks_057","grim",2,"reg=law|mood=sad|world=vehicle,building",{1,"Wanda asked me last night if I'd quit, straight out, at the table",2,"What'd you say?",1,"I said pass the salt, then I sat in the truck in the driveway till half past two"}},
{"s13_ksp_post4_hollow_014","grim",2,"reg=law|mood=grim|world=door",{1,"I drove to the post, doors unlocked, lights on, fan still going in the radio room",2,"Anybody?",1,"Coffee pot was on the burner, burnt black clean through - that's the part I keep coming back to"}},
{"s13_ksp_429_silent_016","grim",2,"reg=law|role=law_trooper|mood=grim|world=vehicle,door",{1,"Anybody put eyes on 429?",2,"Car's on the shoulder at Ekron, driver door open, radio keyed down",1,"Keyed down how?",2,"Mic wedged under the seat, he'd been transmitting a long while before the battery gave"}},
{"s13_ksp_message_16_030","grim",2,"reg=law|mood=sad|world=door",{1,"Message sixteen I ain't delivered",2,"Who's it for?",1,"Mrs. Cundiff, from her husband - he put it on a cassette in his cruiser and I'm the one's got it",2,"Deliver it",1,"I know, I'm going to - it's been in the door pocket four days"}},
{"s13_ksp_open_road_037","grim",1,"reg=law|mood=grim|world=road",{1,"The road's the strangest part, I've run 31W ten thousand times and it's the same road",1,"Same cut, same sign for the cave place, same hill where the deer come out",1,"It's just nobody's on it, feels like a Sunday that won't quit"}},
{"s13_ksp_coroner_number_040","grim",2,"reg=law|mood=grim",{1,"Coroner gave me a case number for the woman at the rest area - then four more, blank",2,"Blank?",1,"Said fill 'em in as I go, he was real polite about it too"}},
{"s13_ksp_last_transmission_047","grim",2,"reg=law|mood=grim",{1,"If I quit answering, what do you do?",2,"Don't ask me that",1,"Answer it - what do you do?",2,"Wait a day, go look - take the notebook out of your car and keep the seven and seven going"}},
{"s13_ksp_speed_limit_sign_053","grim",1,"reg=law|mood=grim",{1,"Speed limit sign at the county line's got four bullet holes in it - always did have",1,"Somebody added two more since the fourth, fresh ones, no rust on 'em",1,"That's how I know folks are still coming through, it ain't a great way to know it"}},
{"s13_ksp_unit_429_car_056","grim",3,"reg=law|mood=sad|world=vehicle,road",{1,"We towed 429's car in",2,"With what?",1,"Farm tractor and a chain, took an hour and a half",3,"Why'd you bother?",1,"His name's on the paperwork and his hat's in the back seat - wasn't leaving either on that road"}},
{"s13_ksp_cruiser_bible_060","grim",1,"reg=law|mood=sad",{1,"Fella left a Bible on my hood at the church lot - set it down, walked off, never said a word",1,"Got a name in the front of it - Roy Buckner, 1961",1,"It's in the door pocket next to the tape I ain't delivered - two things I'm carrying for other people"}},
{"s13_wire_sick_or_bit_022","grim",2,"reg=military|mood=grim",{1,"Two sick - sick how?",2,"Fever, won't eat - Napier's got a bandage on his forearm he won't take off",1,"Then you already know - say it or don't, but you know"}},
{"s13_wire_they_dont_stop_032","grim",2,"reg=military|mood=grim",{1,"Warning shots don't work on 'em",2,"I know it",1,"Nothing on that card works on 'em, the card was wrote for people"}},
{"s13_wire_first_one_033","grim",3,"reg=military|mood=grim",{1,"How many so far?",2,"At this post? Forty-some",3,"Forty-one, I been counting",1,"Don't count",3,"Somebody's going to ask, I'd rather be the one who knows"}},
{"s13_wire_including_people_034","grim",2,"reg=military|hour=16,5|mood=grim",{1,"Is that number just them, or is it everybody?",2,"Don't ask me that on the line",1,"I'm asking",2,"It's everybody - come find me tonight and I'll give you the split"}},
{"s13_wire_first_shot_040","grim",2,"reg=military|mood=fear|world=road",{1,"Who fired?",2,"Me",1,"At what?",2,"The road, ten feet ahead of a Ford - it stopped, everybody's alive and I'm going to be sick now"}},
{"s13_wire_no_ambulance_052","grim",2,"reg=military|mood=grim",{1,"Rodgers' leg's laid open from the wire and the aid station is a tent with one cot in it",2,"Who's stitching?",1,"Me, and I'm the cook"}},
{"s13_eng_family_watched_019","grim",2,"reg=military|mood=sad",{1,"Family stood up on the ridge and watched us do it",2,"Say anything?",1,"Man took his hat off, I don't know what for and I ain't going to guess"}},
{"s13_eng_own_county_025","grim",3,"reg=military|mood=sad",{1,"My daddy poured the deck on the Carver bridge in 1958",2,"You never said that",1,"Didn't see the point in it till today",3,"You want somebody else to hit the machine?",1,"No, I want to hit it myself and I want one other man to know he poured it"}},
{"s13_eng_road_names_026","grim",1,"reg=military|mood=grim|world=road",{1,"Tanner Road, the Echo Creek low water crossing, the Carver approach",1,"Three roads I've taken out of this county in nine days",1,"I know every one of 'em with my eyes shut - learned to drive on two of 'em"}},
{"s13_eng_ear_ringing_028","grim",2,"reg=military|mood=funny",{1,"My left ear's been singing since the bridge",2,"You wear the plugs?",1,"One of 'em, other one's in the truck ashtray where I put it in 1990"}},
{"s13_mp_funeral_detail_055","grim",2,"reg=military|hour=16,5|mood=sad",{1,"They want two of us for a funeral detail in the morning",2,"Whose?",1,"Deel's",2,"... Then it's me and Loveless, and we'll press the uniforms tonight"}},
{"s13_delta_list_of_names_031","grim",1,"reg=elite|role=elite_delta|mood=sad",{1,"I keep a list, folded up, in the waterproof bag with the maps",1,"Just names and dates and one word each, nothing official",1,"When there's an address to send it to, I'll send it - till then it stays in the bag"}},
{"s13_delta_medic_says_032","grim",2,"reg=elite|mood=grim",{1,"How long from the bite?",2,"Hours, sometimes a day - it don't care who you are or how fit you are",1,"Anybody up the chain know that?",2,"I put it in a report in June and I have not heard one word back about it since"}},
{"s13_delta_tell_wife_055","grim",2,"reg=elite|role=elite_delta|mood=sad",{1,"If it goes bad, what do I tell your wife?",2,"Tell her I was working and I wasn't scared",1,"She won't believe the second part",2,"She'll know I said it and she'll know why, that part's for her, not for you"}},
{"exp_prison_chess","inside_memory",2,"reg=prison|st=neutral,careful",{1,"Guy I played chess with, every time I'd win he had a new rule",2,"Why'd you keep playing him?",1,"What else was I gonna do?",2,"Yeah, stupid question"}},
{"s13_law_jailer_elected_002","jail",2,"reg=law|tmp=seasoned",{1,"Jailer's an elected office in this state - elected, same as a magistrate",2,"So?",1,"I knew one who got his job shaking hands at a fish fry. Then got handed nineteen people's lives",2,"Wasn't afraid of a shovel when we needed one, though. Give him that much"}},
{"s13_law_arraign_048_003","jail",2,"reg=law|role=law_deputy,law_corrections|mood=grim",{1,"Got a man in cell two picked up Thursday, forty-eight hours means I take him before a judge",2,"Judge Ferrell's in Lexington with his daughter, nobody's heard from the other one",1,"Then he's a fella in a room and I'm a man who locked it - that's all either of us is",2,"Write the time down, whoever comes after can argue about it"}},
{"s13_law_prisoner_release_031","jail",2,"reg=law|role=law_corrections,law_sheriff",{1,"We're letting out everybody under a year",2,"Including the fella who beat his brother with a jack handle?",1,"Including him, I don't have the food and I don't have the men",2,"Write his name somewhere I can find it"}},
{"s13_law_corrections_count_047","jail",2,"reg=law|role=law_corrections|tmp=seasoned",{1,"Count at six, count at two, count at ten, I've done the count my whole adult life",2,"You miss doing the count?",1,"I miss knowing when it was right. Used to feel like one thing I could put right"}},
{"s13_law_trustee_kitchen_048","jail",2,"reg=law|mood=warm|world=door,fence,building",{1,"Trustees are still cooking - you believe that?",2,"Why wouldn't they?",1,"Doors are open, fence is cut - beans go on at eleven and they're standing there stirring 'em",2,"It's their kitchen too, where's a man go from a kitchen"}},
{"s13_ksp_statewide_007","law",2,"reg=law|role=law_trooper",{1,"A trooper's got arrest powers in every county in the Commonwealth - all hundred and twenty",2,"So?",1,"So I'm the only law that's legal in Knox, Hardin and Meade all at once",1,"And it ain't worth a nickel, there's no court sitting in any of the three"}},
{"s13_ksp_frankfort_order_033","law",3,"reg=law|mood=angry",{1,"Frankfort put out an order, troopers withdraw to the post and hold",2,"Hold what? The post's empty",3,"Hold the post",1,"Yeah, I read it out loud twice and it did not get better the second time"}},
{"s13_ksp_refuse_order_034","law",2,"reg=law|role=law_trooper",{1,"You're staying in the county against an order",2,"I'm staying 'cause the order says report to a post that ain't got a soul in it",1,"They'll write you up",2,"Then somebody up there is typing, and that's the best news I've had all month"}},
{"s13_ksp_two_hats_052","law",2,"reg=law",{1,"Deputy asked me who's in charge at a scene, him or me",2,"What'd you say?",1,"Whoever gets there first and whoever's still standing, he didn't like it - he wrote it down"}},
}
